  return h+'<div class="panel"><h2>저장한 포인트 '+F.length+'곳'+(state.cmp.length?' <a href="#compare">비교표</a>':'')+'</h2>'+(F.length?'<div class="list">'+F.map(function(x){return item({href:'#spot-'+x.id,thumb:x.color,t:x.name,s:x.country+' · '+x.kind});}).join('')+'</div>':'<p class="empty">포인트 화면에서 저장을 눌러 보세요.</p>')+'<p class="small" style="margin:8px 0 0">저장한 포인트는 이 기기에 보관돼요.'+(BE.on?' 로그 · 장비 · 게시물은 계정에 저장돼요.':'')+'</p></div>';
