function upload(bucket,blob,name){var path=BE.user.id+'/'+Date.now()+'-'+Math.random().toString(36).slice(2,8)+'-'+String(name||'file').replace(/[^\w.\-]/g,'_').slice(-40);return BE.sb.storage.from(bucket).upload(path,blob,{upsert:false,contentType:blob.type||undefined}).then(function(r){if(r.error)throw r.error;return path;});}
